    "collapsed": 390,
    "height": "space/16",
    "gutterWide": "space/12",
    "gutterCollapsed": "space/4",
    "barGap": "space/6",
    "linkGap": "space/10",
    "drawerGap": "space/6",
    "drawerTop": "space/4",
    "drawerBottom": "space/8",
    "underlinePad": "space/1",
    "toggle": "space/10",
    "weight": "border-width/default",
    "shadow": "shadow/md",
    "textStyle": "label",
    "background": "color/background",
    "border": "color/border",
    "text": "color/text",
    "muted": "color/text-muted",
